using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.GroupAlgebra;

internal sealed class PGroupAugmentationPrimePowerDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Split augmentation sharpens the transport of modular nilpotence to arithmetic coefficients.",
        H("Augmentation Ideals over Coefficients with Nilpotent p"),
        Blocks(Describe.Lean(
            DescribeId.Create("p-group-augmentation-prime-power-bound"),
            DeclarationHandle.Create("D5/S3/FiniteGroups/GroupAlgebra/PGroupAugmentationPrimePower.augmentation_ideal_pow_pred_card"),
            H("Each scalar layer costs the group order minus one"),
            StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("Let p be prime, a a positive natural number, R any commutative ring with identity, and G any finite p-group of order n. Assume the scalar p in R has a-th power zero. For the actual augmentation homomorphism epsilon from R[G] to R, which sends every group basis element to one, its kernel I satisfies I raised to a times (n minus one) plus one equals zero. The group may be nonabelian. The coefficient and group universes are independent, and the zero ring and trivial group are included. No field, domain, local, Noetherian, coefficient finiteness or module finiteness assumption is used.")),
                Paragraph(Text("In a nonzero coefficient ring, the principal ideal (p) is proper: an equation c p = 1 would give c raised to a times p raised to a equals 1, contradicting the hypothesis. Thus the quotient R/(p) is nonzero, and the vanishing of its scalar p gives characteristic p because p is prime. The original coefficient ring need not have characteristic p. The zero coefficient ring is handled separately.")),
                Paragraph(Text("Reduce every coefficient to obtain rho from R[G] to (R/(p))[G]. Its kernel is exactly J = p R[G], the principal ideal generated by the scalar basis element single 1 p. Indeed, rho(x) = 0 says every coefficient of x is a multiple of p. Decomposing x into its finitely many basis terms expresses it in J, and the generator of J maps to zero. In particular J is two-sided, as a ring-homomorphism kernel.")),
                Paragraph(Text("Augmentation commutes with coefficient reduction. The repository theorem PGroupAugmentation.augmentation_ideal_pow_card applied over R/(p) therefore gives I raised to the cardinality of G contained in p R[G]. The proof transports powers by induction using products and comaps of ideals. It does not require a semiring of all left ideals in a noncommutative group algebra, nor does it require proving that rho maps I onto the entire quotient augmentation ideal.")),
                Paragraph(Text("The R-linear section r maps to r[1] splits epsilon and proves the exact identity I intersect J equals J times I, also written pI. For y in the intersection, write y = p x using centrality of the scalar. Applying epsilon gives p epsilon(x) = 0. Replace x by z = x minus epsilon(x)[1]. Then epsilon(z) = 0 and p z = y, so y belongs to J times I. The reverse inclusion follows from ideal multiplication. No cancellation of p occurs: epsilon(x) itself need not be zero. Since n is positive and I raised to n is contained in I, coefficient reduction now gives I raised to n contained in J times I.")),
                Paragraph(Text("Induction proves I raised to k times (n minus one) plus one is contained in J raised to k times I for every natural k. The base is I contained in J raised to zero times I. For the step, multiply by I raised to n minus one, use associativity to obtain J raised to k times I raised to n, and use the improved inclusion to gain one factor of J. The proof uses the actual two-sided ideal power and multiplication APIs in the possibly noncommutative group algebra. When n is one the same induction applies and gives exponent one.")),
                Paragraph(Text("The scalar p is central, so the a-th power of its principal ideal is the principal ideal generated by p raised to a; hence (p R[G]) raised to a is zero. Taking k = a in the filtration proves the stated exponent a times (n minus one) plus one. The source does not assert minimality or formalize a separate sharpness lower bound.")),
                Paragraph(Text("This coefficient extension supplies an arithmetic input for the orbit-sum, norm and projectivity program: the group-order filtration remains controlled when p itself survives but is nilpotent. Splitting augmentation retains the augmentation factor at each scalar layer and improves the quantitative control. Further module-theoretic conclusions are motivations and are not additional theorems asserted by this declaration. The assessment is repository-derived: PGroupAugmentation.augmentation_ideal_pow_card is reused directly, while coefficient reduction and the split intersection supply the extension. The split-filtration argument follows the supplied GPT Pro derivation. No literature citation is claimed to state this full bound, and no literature novelty or historical priority is claimed."))),
            DescribeRole.Theorem))));
}
